const { existsSync } = await import('node:fs');
const inputPath = process.env.HTML_PATH;
if (!inputPath) { throw new Error('Missing required input html_path'); }
if (!existsSync(inputPath)) { throw new Error('Input file does not exist: ' + inputPath); }
globalThis.htmlPath = inputPath;
const outPath = '/tmp/output.pdf';
globalThis.outPath = outPath;

const mod = await import('topdf');
const fn = mod.default || mod;
await fn(globalThis.htmlPath, globalThis.outPath);
globalThis.resultPath = globalThis.outPath;
